newcode='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg]
    # The two long edge segments are matching rails. A scattered color marks
    # offsets along the rail; each marked offset projects inward from both rails.
    candidates = []
    for fixed, edge in ((0, 'top'), (h - 1, 'bottom')):
        row = grid[fixed]
        for color in set(row):
            if color == bg: continue
            coords = [c for c, v in enumerate(row) if v == color]
            if len(coords) >= 2 and coords == list(range(min(coords), max(coords) + 1)):
                candidates.append((edge, color, min(coords), max(coords), 'h'))
    for fixed, edge in ((0, 'left'), (w - 1, 'right')):
        col = [grid[r][fixed] for r in range(h)]
        for color in set(col):
            if color == bg: continue
            coords = [r for r, v in enumerate(col) if v == color]
            if len(coords) >= 2 and coords == list(range(min(coords), max(coords) + 1)):
                candidates.append((edge, color, min(coords), max(coords), 'v'))
    pairs = []
    for a in candidates:
        for b in candidates:
            if a[0] == 'top' and b[0] == 'bottom' or a[0] == 'left' and b[0] == 'right':
                if a[1] == b[1] and a[4] == b[4] and a[3] - a[2] == b[3] - b[2]:
                    pairs.append((a, b))
    if not pairs:
        return out
    a, b = pairs[0]
    bar_color = a[1]
    scattered = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                 if grid[r][c] != bg and grid[r][c] != bar_color]
    if not scattered:
        return out
    fill_color = scattered[0][2]
    axis = 1 if a[4] == 'h' else 0
    start_a, start_b = a[2], b[2]
    marked_offsets = {((c if axis else r) - start_a) for r, c, _ in scattered
                      if start_a <= (c if axis else r) <= a[3]}
    if not marked_offsets:
        return out
    for r, c, _ in scattered:
        out[r][c] = 4
    for rail in (a, b):
        edge, _, lo, hi, orient = rail
        for offset in marked_offsets:
            pos = lo + offset
            if orient == 'h':
                rr = 1 if edge == 'top' else h - 2
                step = 1 if edge == 'top' else -1
                while 0 <= rr < h:
                    if grid[rr][pos] == fill_color:
                        break
                    if grid[rr][pos] != bg:
                        break
                    out[rr][pos] = fill_color
                    rr += step
            else:
                cc = 1 if edge == 'left' else w - 2
                step = 1 if edge == 'left' else -1
                while 0 <= cc < w:
                    if grid[pos][cc] == fill_color:
                        break
                    if grid[pos][cc] != bg:
                        break
                    out[pos][cc] = fill_color
                    cc += step
    return out
